{
  "nombre": "El Español",
  "titular_real": "Feijóo carga contra Puente: \"Echó la culpa a un operador de Atocha y eso es una frivolidad impropia de un ministro\"",
  "titular_traducido": "Feijóo ataca a Puente con tono de superioridad: la culpa de lo ocurrido en Atocha se habría desplazado a un “operador”, y el medio vende esa respuesta como “frívola” y “no ministerial”, insinuando incompetencia sin entrar en pruebas ni contexto.",
  "imd_local": {
    "intencion_probable": "Activar alineamiento político y credibilidad desde el juicio moral (“impropia de un ministro”) más que desde la verificación de hechos.",
    "marco_emocional": "Indignación y deslegitimación del adversario mediante etiquetas valorativas."
  },
  "framing": "Framing de descalificación personal/institucional: se presenta la reacción del rival (Puente) como un fallo impropio del cargo, desplazando el foco desde el hecho controvertido hacia el “estilo” y la “seriedad” del ministro.",
  "palabra_cuchillo": "impropia",
  "tecnica_principal": "Apelación al juicio moral y al desprestigio por tono (adjetivación valorativa para invalidar al rival).",
  "omision": "Se omite qué ocurrió exactamente en Atocha, qué hechos concretos sustentan la atribución de culpa a un operador, qué parte es responsabilidad política y cuál es técnica/operativa, y si existe respuesta documental o datos verificables; también se omite el contexto completo de la declaración y posibles matices (por ejemplo, si se trataba de un apunte operativo o de una atribución probada)."
}
